export function ProgressiveRendering({
  stage = "{{stage}}",
  accent = "{{accent}}",
  showLabels = {{showLabels}},
  pageTitle = "{{pageTitle}}",
}) {
  const shown = { header: stage !== "none", content: stage === "content" || stage === "complete", comments: stage === "complete" };
  const block = (visible, label) => (
    <div style={{ height: 34, borderRadius: 8, marginBottom: 8, opacity: visible ? 1 : .15, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 700, background: accent }}>
      {showLabels && label}
    </div>
  );
  return (
    <div role="img" aria-label={`${pageTitle} progressively rendered, stage: ${stage}`} style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontWeight: 700 }}>{pageTitle}</p>
      {block(shown.header, "Header (painted first)")}
      {block(shown.content, "Article body (streamed in)")}
      {block(shown.comments, "Comments (last)")}
    </div>
  );
}
